def gen(rng):
    def fmt(a, t):
        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + str(t)
    def arr(n, lo, hi):
        return sorted(rng.sample(range(lo, hi + 1), n))
    tests = [fmt([5], 5), fmt([5], 4), fmt([5], 6), fmt([1, 2], 1), fmt([1, 2], 2), fmt([1, 2], 3),
             fmt([-10**9, 10**9], -10**9), fmt([-10**9, 10**9], 10**9), fmt([-10**9, 10**9], 0)]
    for n in (3, 4, 7, 10, 15, 30):
        for _ in range(2):
            a = arr(n, -50, 50)
            tests.append(fmt(a, rng.choice(a)))
            tests.append(fmt(a, rng.randint(-60, 60)))
    N = 100000
    a = arr(N, -10**9, 10**9)
    tests.append(fmt(a, a[0]))
    tests.append(fmt(a, a[-1]))
    tests.append(fmt(a, a[N // 2]))
    tests.append(fmt(a, a[0] - 1 if a[0] > -10**9 else a[-1]))
    tests.append(fmt([i + 1 for i in range(N)], N + 1))
    return tests
